mapper.select:
select hli.lease_item_id, hli.full_name, hli.LEASE_ITEM_TYPE, (select meaning from sys_code_value_b_v where code = 'HLS.COLLATERAL_TYPE' and code_value = hli.LEASE_ITEM_TYPE) LEASE_ITEM_TYPE_N, -- hli.PATTERN, (select meaning from sys_code_value_b_v where code in ('HLS.COLLATERAL_TYPE','HLS.PLEDGE_TYPE') and code_value = hli.PATTERN) PATTERN_N, hli.REGULATORY_ASSET_CLASS, (select t.description from hls_business_type t where t.document_category = 'REGULATORY_ASSET_CLASS' and t.business_type = hli.REGULATORY_ASSET_CLASS) REGULATORY_ASSET_CLASS_N, hli.REGULATORY_ASSET_CLASS_SUB, (select t.description from hls_document_type t where t.document_category = 'REGULATORY_ASSET_CLASS' and t.business_type = hli.REGULATORY_ASSET_CLASS and t.document_type = hli.REGULATORY_ASSET_CLASS_SUB) REGULATORY_ASSET_CLASS_SUB_N, hli.collateral_categories, (select t.description from hls_collateral_categories t where t.collateral_categories = hli.collateral_categories) collateral_categories_N, hli.collateral_classify_one, (select t.description from hls_collateral_classify_one t where t.collateral_classify_one = hli.collateral_classify_one) collateral_classify_one_N, hli.collateral_classify_two, (select t.description from hls_collateral_classify_two t where t.collateral_classify_two = hli.collateral_classify_two) collateral_classify_two_N, hli.MORTGAGOR, (select su.description from sys_user su where su.user_id = hli.MORTGAGOR) MORTGAGOR_N, hli.MORTGAGE_SEQUENCE, (select meaning from sys_code_value_b_v where code = 'HLS.MORTGAGE_SEQUENCE' and code_value = hli.MORTGAGE_SEQUENCE) MORTGAGE_SEQUENCE_N, hli.MORTGAGE_DATE_FROM, hli.mortgage_date_to, hli.MORTGAGE_AMOUNT, hli.CURRENCY, (select meaning from sys_code_value_b_v where code = 'CHS.CURRENCY_TYPE' and code_value = hli.CURRENCY) CURRENCY_N, hli.ASSET_VALUE, hli.VALUATION_DATE, hli.VALUATION_UNIT, hli.USAGE_TYPE, (select meaning from sys_code_value_b_v where code = 'HLS.USAGE_TYPE' and code_value = hli.USAGE_TYPE) USAGE_TYPE_N, hli.BUILDING_AREA, hli.EQUITY_NUMBER, hli.FLOOR_AREA, hli.IF_SINCE_THE_MORTGAGE, (select meaning from sys_code_value_b_v where code = 'SYS.YES_NO' and code_value = hli.IF_SINCE_THE_MORTGAGE) IF_SINCE_THE_MORTGAGE_N, hli.LAND_LOCATED, hli.LAND_USE from hls_lease_item hli,prj_project_pledge ppp
hli.LEASE_ITEM_TYPE in ('MORTGAGE','PLEDGE') and hli.lease_item_id = ppp.lease_item_id
and ppp.project_id = #{projectId}
